import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import MapPicker from "../MapPicker";
import "./HousePredictionForm.css";

export default function HousePredictionForm() {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    area: "",
    propertyType: "",
    bedrooms: "",
    bathrooms: "",
    year: "",
    condition: "",
  });
  const [location, setLocation] = useState({
    lat: null,
    lng: null,
    address: "",
  });
  const [result, setResult] = useState();
  const [loading, setLoading] = useState(false);

  const handleFormChange = (e) =>
    setForm({ ...form, [e.target.name]: e.target.value });

  const handleLocationChange = (loc) => {
    setLocation(loc);
  };

  const getCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert("Geolocation is not supported by this browser.");
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (position) => {
        const lat = position.coords.latitude;
        const lng = position.coords.longitude;
        // Reverse geocode using Google Maps Geocoding API to get address
        fetch(
          `https://maps.googleapis.com/maps/api/geocode/json?latlng=${lat},${lng}&key=${process.env.REACT_APP_GOOGLE_MAPS_API_KEY}`
        )
          .then((res) => res.json())
          .then((data) => {
            if (data.status === "OK") {
              const firstResult = data.results[0];
              setLocation({
                lat,
                lng,
                address: firstResult.formatted_address,
              });
            } else {
              alert("Failed to get address from location.");
            }
          });
      },
      () => {
        alert("Permission denied or unable to get location.");
      },
      { enableHighAccuracy: true }
    );
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!location.lat || !location.lng) {
      alert("Please select a location.");
      return;
    }
    const payload = {
      location: location.address,
      area: form.area,
      propertyType: form.propertyType,
      bedrooms: form.bedrooms,
      bathrooms: form.bathrooms,
      year: form.year,
      condition: form.condition,
      latitude: location.lat,
      longitude: location.lng,
    };

    setLoading(true);
    setResult(null);
    try {
      const response = await fetch(
        `${process.env.REACT_APP_BACKEND_URL}/predict/house`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        }
      );
      const data = await response.json();
      setResult(data.price);
    } catch (error) {
      console.error(error);
      setResult("Prediction failed.");
    }
    setLoading(false);
  };

  return (
    <div className="house-predict-root">
      <button className="back-btn" onClick={() => navigate("/")}>
        ← Back to Home
      </button>
      <div className="house-predict-panels">
        <div className="property-details-card">
          <h2>Property Details</h2>
          <p>Enter the details of the house to get an accurate price prediction</p>

          <button onClick={getCurrentLocation} className="location-btn">
            Use My Location
          </button>

          <MapPicker location={location} onLocationChange={handleLocationChange} />

          <form onSubmit={handleSubmit} className="property-form">
            <input
              type="text"
              name="location"
              placeholder="Selected Address"
              value={location.address}
              readOnly
              className="input-location"
            />

            <label>Area (sq ft)</label>
            <input
              name="area"
              type="number"
              min="0"
              placeholder="1500"
              value={form.area}
              onChange={handleFormChange}
              required
            />

            <label>Property Type</label>
            <select
              name="propertyType"
              value={form.propertyType}
              onChange={handleFormChange}
              required
            >
              <option value="">Select type</option>
              <option>Apartment</option>
              <option>Villa</option>
              <option>Independent House</option>
              <option>Duplex</option>
            </select>

            <label>Bedrooms</label>
            <select
              name="bedrooms"
              value={form.bedrooms}
              onChange={handleFormChange}
              required
            >
              <option value="">Select bedrooms</option>
              {[1, 2, 3, 4, 5].map((b) => (
                <option key={b} value={b}>
                  {b}
                </option>
              ))}
            </select>

            <label>Bathrooms</label>
            <select
              name="bathrooms"
              value={form.bathrooms}
              onChange={handleFormChange}
              required
            >
              <option value="">Select bathrooms</option>
              {[1, 2, 3, 4, 5].map((b) => (
                <option key={b} value={b}>
                  {b}
                </option>
              ))}
            </select>

            <label>Year Built</label>
            <input
              name="year"
              type="number"
              min="1900"
              max={new Date().getFullYear()}
              placeholder="2015"
              value={form.year}
              onChange={handleFormChange}
            />

            <label>Condition</label>
            <select name="condition" value={form.condition} onChange={handleFormChange}>
              <option value="">Select condition</option>
              <option>Excellent</option>
              <option>Good</option>
              <option>Needs Renovation</option>
            </select>

            <button type="submit" disabled={loading}>
              {loading ? "Predicting..." : "Predict House Price"}
            </button>
          </form>
        </div>

        <div className="price-prediction-card">
          <h2>Price Prediction</h2>
          <p>Your estimated house price will appear here</p>
          {result !== null && <div className="price-result">₹ {result}</div>}
        </div>
      </div>
    </div>
  );
}
